with filtered as (select *, datediff(current_date(), starts_on) as days_since_starts_on from promotions where ends_on >= date '2023-08-26'), latest as (select * from filtered qualify rank() over (partition by channel order by discount_pct desc) = 1), enriched as (select id, channel, promo_code, starts_on, ends_on, count(days_since_starts_on) over w_running as running_count_days_since_starts_on, sum(days_since_starts_on) over w_running as running_sum_days_since_starts_on, avg(days_since_starts_on) over w_running as running_avg_days_since_starts_on, min(days_since_starts_on) over w_running as running_min_days_since_starts_on, last_value(days_since_starts_on, true) over (partition by channel order by days_since_starts_on asc, id asc rows between unbounded preceding and current row) as last_known_days_since_starts_on from latest window w_running as (partition by promo_code order by discount_pct asc, id asc rows between unbounded preceding and current row)), with_window as (select a.*, pr.id as promo_id, pr.promo_code as promotion_promo_code, pr.discount_pct from enriched a left join promotions pr on a.channel = pr.channel and a.ends_on >= pr.starts_on and a.ends_on < pr.ends_on + interval '14' day), totals as (select date_trunc('quarter', ends_on) as quarter_start, promo_id, max(running_min_days_since_starts_on) as max_running_min_days_since_starts_on, round(sum(discount_pct) / nullif(count(case when channel = 'partner' then 1 end), 0), 2) as discount_pct_per_partner, size(collect_set(channel)) as num_channels, round(avg(last_known_days_since_starts_on), 2) as avg_last_known_days_since_starts_on, count(case when promotion_promo_code = 'VIP' then 1 end) as vip_count, dense_rank() over (partition by date_trunc('quarter', ends_on) order by size(collect_set(channel)) desc) as num_channels_dense_rank from with_window group by date_trunc('quarter', ends_on), promo_id) select quarter_start, promo_id, max_running_min_days_since_starts_on, num_channels, vip_count, num_channels_dense_rank from totals order by quarter_start desc nulls last;
